INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4982776, 725086, 99063, '<td valign="top">I think the subject material is awesome -- but as far as the actual photo goes you could''ve done a lot more with it....</td>', 'I think the subject material is awesome -- but as far as the actual photo goes you could''ve done a lot more with it....', '2008-10-01 01:11:55.000000', NULL, 1),
(4982891, 726774, 99063, '<td valign="top">haha!  Great idea!!  :)</td>', 'haha!  Great idea!!  :)', '2008-10-01 01:25:05.000000', NULL, 1),
(4982953, 726865, 99063, '<td valign="top">Is this photoshopped?  Are you allowed to do that in a Basic Editing Challenge?  (I''m just asking ''cause I don''t know.)</td>', 'Is this photoshopped?  Are you allowed to do that in a Basic Editing Challenge?  (I''m just asking ''cause I don''t know.)', '2008-10-01 01:31:40.000000', NULL, 1),
(4983034, 724656, 88254, '<td valign="top">Go Love Shack!</td>', 'Go Love Shack!', '2008-10-01 01:43:52.000000', NULL, 1),
(4983055, 727142, 88254, '<td valign="top">Go Love Shack!</td>', 'Go Love Shack!', '2008-10-01 01:46:33.000000', NULL, 1),
(4983096, 726973, 56254, '<td valign="top">fantastic idea ... good luck!</td>', 'fantastic idea ... good luck!', '2008-10-01 01:53:14.000000', NULL, 1),
(4983119, 727177, 97282, '<td valign="top">:) Love the expression on his face!</td>', ':) Love the expression on his face!', '2008-10-01 01:57:30.000000', NULL, 1),
(4983190, 724656, 73452, '<td valign="top">i know who this is!  Great to see another self portrait!  i think, i hope this is who i think it is!  haha, if you have no idea what im talking about, im so sorry!  great shot though!</td>', 'i know who this is!  Great to see another self portrait!  i think, i hope this is who i think it is!  haha, if you have no idea what im talking about, im so sorry!  great shot though!', '2008-10-01 02:04:46.000000', NULL, 1),
(4983195, 726973, 97282, '<td valign="top">WOW, great shot!  Love the composition.</td>', 'WOW, great shot!  Love the composition.', '2008-10-01 02:05:42.000000', NULL, 1),
(4983206, 726632, 97282, '<td valign="top">Very Cute!</td>', 'Very Cute!', '2008-10-01 02:06:16.000000', NULL, 1),
(4983269, 725275, 70375, '<td valign="top">Very unique idea. I would like to see the pajamas take center stage a bit more but I do like the snake''s tongue hanging out. The threads in the foreground are a bit of "clutter" and if removed would have made for a bit of a cleaner image. Your lighting is nice. Great colour.</td>', 'Very unique idea. I would like to see the pajamas take center stage a bit more but I do like the snake''s tongue hanging out. The threads in the foreground are a bit of "clutter" and if removed would have made for a bit of a cleaner image. Your lighting is nice. Great colour.', '2008-10-01 02:15:47.000000', NULL, 1),
(4983278, 727081, 70375, '<td valign="top">Cute. I would like to see either a greater or shallower DOF though. I like the backlighting, it''s nice coming through the PJs. Very vibrant and interesting to look at. There are a few things that could have improved this, but they are minor. Good job.</td>', 'Cute. I would like to see either a greater or shallower DOF though. I like the backlighting, it''s nice coming through the PJs. Very vibrant and interesting to look at. There are a few things that could have improved this, but they are minor. Good job.', '2008-10-01 02:17:42.000000', NULL, 1),
(4983290, 727205, 73452, '<td valign="top">ahhhh!  this was from one of the dpcers that went to the salt flats last week.  i so wish i could have been tbhere with you guys.  good luck!</td>', 'ahhhh!  this was from one of the dpcers that went to the salt flats last week.  i so wish i could have been tbhere with you guys.  good luck!', '2008-10-01 02:19:07.000000', NULL, 1),
(4983308, 725309, 70375, '<td valign="top">Interesting idea. I think it would have behooved this image to include more of the PJs though. Perhaps a full length shot? It also looks just a hair too contrasty. There is some detail in the shadows that is hard to make out.</td>', 'Interesting idea. I think it would have behooved this image to include more of the PJs though. Perhaps a full length shot? It also looks just a hair too contrasty. There is some detail in the shadows that is hard to make out.', '2008-10-01 02:20:47.000000', NULL, 1),
(4983324, 725536, 70375, '<td valign="top">They look a little nervous ;) I like this idea. Very well thought out. I would like to see a little more shadows and light and perhaps even more interaction between the two sets of PJs. I am losing a sense of scale here. I can''t decide if those are child or adult PJs. Overall, not bad. :)</td>', 'They look a little nervous ;) I like this idea. Very well thought out. I would like to see a little more shadows and light and perhaps even more interaction between the two sets of PJs. I am losing a sense of scale here. I can''t decide if those are child or adult PJs. Overall, not bad. :)', '2008-10-01 02:24:05.000000', NULL, 1),
(4983336, 726359, 70375, '<td valign="top">This is a fantastic concept. Colours are complimentary and work very well together. A few things detract: The babysitter''s feet are gone. There is an odd light under the boy''s chin. Your background is a bit distracting... Other than that, good job thinking outside the box! :)</td>', 'This is a fantastic concept. Colours are complimentary and work very well together. A few things detract: The babysitter''s feet are gone. There is an odd light under the boy''s chin. Your background is a bit distracting... Other than that, good job thinking outside the box! :)', '2008-10-01 02:26:36.000000', NULL, 1),
(4983357, 726931, 70375, '<td valign="top">The idea is there, but I think it was a little lost in this attempt. You have a very nice B&amp;W conversion here. Light is interesting. I would like to see the PJs take more of a center roll. The dog serves only as a distraction from them here. Perhaps a different angle would have made more of a difference.</td>', 'The idea is there, but I think it was a little lost in this attempt. You have a very nice B&W conversion here. Light is interesting. I would like to see the PJs take more of a center roll. The dog serves only as a distraction from them here. Perhaps a different angle would have made more of a difference.', '2008-10-01 02:29:30.000000', NULL, 1),
(4983381, 726743, 70375, '<td valign="top">I hope you aren''t just going for the brown ribbon here because this is a serious comment. Your image is blurry. Try using either a tripod for long exposure or a flash so you can speed up your shutter. Your colour is way off. WB to tungsten or fluorescent indoors (depending on what kind of light you use). Your focus is way soft. Your fire looks neat but only serves, in this image, to distract from the subject (PJs).</td>', 'I hope you aren''t just going for the brown ribbon here because this is a serious comment. Your image is blurry. Try using either a tripod for long exposure or a flash so you can speed up your shutter. Your colour is way off. WB to tungsten or fluorescent indoors (depending on what kind of light you use). Your focus is way soft. Your fire looks neat but only serves, in this image, to distract from the subject (PJs).', '2008-10-01 02:32:54.000000', NULL, 1),
(4983396, 726884, 62249, '<td valign="top">lighting is kinda harsh. Cute kids, though.</td>', 'lighting is kinda harsh. Cute kids, though.', '2008-10-01 02:35:02.000000', NULL, 1),
(4983410, 727006, 70375, '<td valign="top">Good use of DOF. I would like to see more PJs and less underwear in the shot though. That bright window in the back is a major distraction. At the very least, there should be some light on the PJ bottoms on the bed there.</td>', 'Good use of DOF. I would like to see more PJs and less underwear in the shot though. That bright window in the back is a major distraction. At the very least, there should be some light on the PJ bottoms on the bed there.', '2008-10-01 02:37:27.000000', NULL, 1),
(4983412, 726743, 62249, '<td valign="top">You captured the flames nicely, but the lighting on the rest of the shot is unappealing. Soft focus instead of blur might have worked better.</td>', 'You captured the flames nicely, but the lighting on the rest of the shot is unappealing. Soft focus instead of blur might have worked better.', '2008-10-01 02:37:38.000000', NULL, 1),
(4983415, 725421, 62249, '<td valign="top">Good title. Cute capture. Average photo quality, but decent for Basic editing.</td>', 'Good title. Cute capture. Average photo quality, but decent for Basic editing.', '2008-10-01 02:39:40.000000', NULL, 1),
(4983431, 726957, 62249, '<td valign="top">Cute kids. Needs more interesting lighting.</td>', 'Cute kids. Needs more interesting lighting.', '2008-10-01 02:43:13.000000', NULL, 1),
(4983437, 726720, 62249, '<td valign="top">Naughty ;-). 6</td>', 'Naughty ;-). 6', '2008-10-01 02:44:17.000000', NULL, 1),
(4983444, 726891, 62249, '<td valign="top">Needs better lighting on the gown, but otherwise a good shot.</td>', 'Needs better lighting on the gown, but otherwise a good shot.', '2008-10-01 02:45:23.000000', NULL, 1),
(4983536, 726639, 53594, '<td valign="top">I think this is one of the better photos in this challenge. You could have improved the composition by cropping out the curtain to the right and the  and the bed frames. Overall an amusing photo. Good Luck</td>', 'I think this is one of the better photos in this challenge. You could have improved the composition by cropping out the curtain to the right and the  and the bed frames. Overall an amusing photo. Good Luck', '2008-10-01 03:18:29.000000', NULL, 1),
