(4983552, 725309, 97225, '<td valign="top">That''s a great match. Very effective.</td>', 'That''s a great match. Very effective.', '2008-10-01 03:30:35.000000', NULL, 1),
(4983554, 727006, 97225, '<td valign="top">Keep them handy in case of fire. Nice interpretation.</td>', 'Keep them handy in case of fire. Nice interpretation.', '2008-10-01 03:32:01.000000', NULL, 1),
