(4983559, 726548, 97225, '<td valign="top">Oh, that is beautiful. So colorful, and I love the composition. I tried to get a clothesline shot, but couldn''t get free of trees, rooves, antennas, no matter how hard I tried. It was never going to measure up to this anyway.</td>', 'Oh, that is beautiful. So colorful, and I love the composition. I tried to get a clothesline shot, but couldn''t get free of trees, rooves, antennas, no matter how hard I tried. It was never going to measure up to this anyway.', '2008-10-01 03:36:36.000000', NULL, 1),
(4983563, 725206, 97225, '<td valign="top">That is a great shot.</td>', 'That is a great shot.', '2008-10-01 03:38:08.000000', NULL, 1),
(4983565, 725613, 97225, '<td valign="top">I love the light in this shot.</td>', 'I love the light in this shot.', '2008-10-01 03:38:44.000000', NULL, 1),
