(4983572, 724859, 97225, '<td valign="top">Good shot.</td>', 'Good shot.', '2008-10-01 03:40:05.000000', NULL, 1),
(4983577, 726706, 97225, '<td valign="top">Or.. It''s a long way to the outhouse. Nice pic.</td>', 'Or.. It''s a long way to the outhouse. Nice pic.', '2008-10-01 03:41:18.000000', NULL, 1),
(4983580, 724656, 97225, '<td valign="top">Wow! Wish I felt like that in the morning. Nice joyful shot.</td>', 'Wow! Wish I felt like that in the morning. Nice joyful shot.', '2008-10-01 03:42:23.000000', NULL, 1),
(4983581, 726891, 97225, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2008-10-01 03:42:58.000000', NULL, 1),
