(4983584, 726334, 97225, '<td valign="top">Cute dog. Smart idea.</td>', 'Cute dog. Smart idea.', '2008-10-01 03:44:39.000000', NULL, 1),
(4983589, 726865, 97225, '<td valign="top">That is an excellent setup. Looks great.</td>', 'That is an excellent setup. Looks great.', '2008-10-01 03:49:46.000000', NULL, 1),
(4983590, 726817, 97225, '<td valign="top">Lovely shot, and great idea.</td>', 'Lovely shot, and great idea.', '2008-10-01 03:50:33.000000', NULL, 1),
