(4984540, 726973, 81530, '<td valign="top">Interesting idea. I''m surprised you have access to that many happy face pajamas..lol</td>', 'Interesting idea. I''m surprised you have access to that many happy face pajamas..lol', '2008-10-01 12:23:50.000000', NULL, 1),
