(4987900, 726723, 98141, '<td valign="top">I would never go Horseback Riding in my pajamas, she is a braver girl than I! Nice DOF.</td>', 'I would never go Horseback Riding in my pajamas, she is a braver girl than I! Nice DOF.', '2008-10-02 19:01:30.000000', NULL, 1),
(4987907, 726963, 98141, '<td valign="top">I think some people are not going to consider these pajamas, but I would sleep in them, so I think they count. I''m not a fan of the framing and I would like it if the detail on the red one was more clear. I like the idea.</td>', 'I think some people are not going to consider these pajamas, but I would sleep in them, so I think they count. I''m not a fan of the framing and I would like it if the detail on the red one was more clear. I like the idea.', '2008-10-02 19:03:07.000000', NULL, 1),
(4987910, 726706, 98141, '<td valign="top">I like the trail from the stick draggin in the ground, nice detail.</td>', 'I like the trail from the stick draggin in the ground, nice detail.', '2008-10-02 19:03:34.000000', NULL, 1),
(4987912, 726642, 98141, '<td valign="top">Your title makes me imagine PB&amp;J (jam). I like the colors a lot.</td>', 'Your title makes me imagine PB&J (jam). I like the colors a lot.', '2008-10-02 19:04:33.000000', NULL, 1),
(4987915, 726663, 98141, '<td valign="top">That is a huge bottle. I like the idea, and who isn''t a Tigger fan? Well done.</td>', 'That is a huge bottle. I like the idea, and who isn''t a Tigger fan? Well done.', '2008-10-02 19:05:06.000000', NULL, 1),
(4987919, 726711, 98141, '<td valign="top">This was hard to wrap my brain around at first, it''s almost like an optical illusion.</td>', 'This was hard to wrap my brain around at first, it''s almost like an optical illusion.', '2008-10-02 19:06:01.000000', NULL, 1),
(4987925, 726884, 98141, '<td valign="top">So cozy! Even the teddy bears have PJs :) This reminds me of the night before Christmas.</td>', 'So cozy! Even the teddy bears have PJs :) This reminds me of the night before Christmas.', '2008-10-02 19:06:55.000000', NULL, 1),
(4987926, 725913, 98141, '<td valign="top">I really enjoy shots like this, where you can''t even be sure that they''re PJs.</td>', 'I really enjoy shots like this, where you can''t even be sure that they''re PJs.', '2008-10-02 19:07:40.000000', NULL, 1),
(4987927, 726497, 98141, '<td valign="top">When my *ahem* friends are drunk, they usually don''t have sense to change into pajamas. I feel like "drunk" PJs would consist more of regular clothes...</td>', 'When my *ahem* friends are drunk, they usually don''t have sense to change into pajamas. I feel like "drunk" PJs would consist more of regular clothes...', '2008-10-02 19:08:31.000000', NULL, 1),
(4987930, 726066, 98141, '<td valign="top">Cutie! For me, this pic is lacking something, but I can''t put my finger on exactly what it is. I think I would like it if the subjects were sharper, but that''s a personal preference.</td>', 'Cutie! For me, this pic is lacking something, but I can''t put my finger on exactly what it is. I think I would like it if the subjects were sharper, but that''s a personal preference.', '2008-10-02 19:09:46.000000', NULL, 1);
