INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4997762, 725317, 91614, '<td valign="top">Wow i really love this shot. The tones are so soft and not harsh at all. Its one of the only black and white images yet it''s one of my favorite photos in the whole challenge. Really great lighting. The title is a little disappointing though. But still a very nice job. 9 :)</td>', 'Wow i really love this shot. The tones are so soft and not harsh at all. Its one of the only black and white images yet it''s one of my favorite photos in the whole challenge. Really great lighting. The title is a little disappointing though. But still a very nice job. 9 :)', '2008-10-07 23:04:45.000000', NULL, 1),
(4997852, 726504, 3936, '<td valign="top">Wonder if this is who I think it is.  Guess I''ll know tomorrow...<br/> <br/>Very cute take on the subject.  Would have liked at but more depth of field, and maybe a little different lighting to get rid of the shadow under "his arm".  But still a very good photo, and a nice change from kids in jammies.</td>', 'Wonder if this is who I think it is.  Guess I''ll know tomorrow... Very cute take on the subject.  Would have liked at but more depth of field, and maybe a little different lighting to get rid of the shadow under "his arm".  But still a very good photo, and a nice change from kids in jammies.', '2008-10-08 00:09:29.000000', NULL, 1),
(4997855, 726774, 3936, '<td valign="top">This is just downright funny!  One of my favorites this challenge.  Hope you do well.</td>', 'This is just downright funny!  One of my favorites this challenge.  Hope you do well.', '2008-10-08 00:11:08.000000', NULL, 1),
(4997938, 727059, 96881, '<td valign="top">A number of these int eh challenge.  I like the adition of the teddy.  Like the gradient through the background as well.  I think this works...</td>', 'A number of these int eh challenge.  I like the adition of the teddy.  Like the gradient through the background as well.  I think this works...', '2008-10-08 00:51:22.000000', NULL, 1),
(4997943, 726533, 96881, '<td valign="top">Very different.  Tricky light makes it tough, as i cuases overexposed areas due to the dappled light, while other features are underexposed.</td>', 'Very different.  Tricky light makes it tough, as i cuases overexposed areas due to the dappled light, while other features are underexposed.', '2008-10-08 00:52:15.000000', NULL, 1),
(4997948, 726735, 96881, '<td valign="top">There looks to be a lot of noise int his photo.  I would have had it in colour to show off the colours of the Pj''s, instead of Black and White</td>', 'There looks to be a lot of noise int his photo.  I would have had it in colour to show off the colours of the Pj''s, instead of Black and White', '2008-10-08 00:53:34.000000', NULL, 1),
(4997956, 727071, 96881, '<td valign="top">"Daddy lets me do it"<br/>You are in sooo much trouble....</td>', '"Daddy lets me do it"You are in sooo much trouble....', '2008-10-08 00:54:47.000000', NULL, 1),
(4997958, 727040, 94265, '<td valign="top">I find this one very funny, imagine how mortified you''d be if they asked for the original file and the shadow wasn''t originally there in *that* area! Haha.</td>', 'I find this one very funny, imagine how mortified you''d be if they asked for the original file and the shadow wasn''t originally there in *that* area! Haha.', '2008-10-08 00:55:23.000000', NULL, 1),
(4997959, 726642, 96881, '<td valign="top">Not a fan of the post processing here.  I think the crop is too close to his head, the border really looks like its constraining him.....</td>', 'Not a fan of the post processing here.  I think the crop is too close to his head, the border really looks like its constraining him.....', '2008-10-08 00:55:34.000000', NULL, 1),
